/** Histogram binning logic (Freedman–Diaconis + fallbacks) extracted for reuse & testing. */
import { HistogramConfig, HistogramComputationResult } from '../state/types';

/** Compute histogram bin parameters for a numeric sample. */
export function computeHistogramBins(
  series: number[],
  sliderVal: number, // 0 => auto
  config: HistogramConfig
): HistogramComputationResult {
  if (!series.length) return {};
  const sorted = [...series].sort((a, b) => a - b);
  const n = sorted.length;
  const min = sorted[0];
  const max = sorted[n - 1];
  const span = max - min;
  if (span === 0) {
    return { xbins: { start: min - 0.5, end: min + 0.5, size: 1 }, nbins: 1 };
  }
  if (sliderVal > 0) {
    const manualBins = Math.max(config.minBinsManual, Math.min(series.length, sliderVal));
    return { nbins: manualBins }; // rely on Plotly binning; avoid manual xbins to prevent float clipping
  }
  // Auto mode: Freedman–Diaconis, fallback to sqrt(n)
  const q1 = sorted[Math.floor(n * 0.25)];
  const q3 = sorted[Math.floor(n * 0.75)];
  const iqr = (q3 - q1) || span || 1;
  const fdWidth = 2 * iqr / Math.cbrt(n);
  if (fdWidth <= 0) {
    const sqrtGuess = Math.ceil(Math.sqrt(n));
    return { nbins: Math.min(config.defaultMaxBins, sqrtGuess) };
  }
  const est = Math.round(span / fdWidth);
  const nbins = Math.max(config.minBins, Math.min(config.maxBins, est));
  return { nbins };
}
