import { END_OF_DAY_PADDING } from '../utils/dateUtils';

export interface DetectionConfig {
  sampleSizeCap: number;
  numericHeuristicMinRatio: number;
  numericHeuristicMinCount: number;
  minNumericValidRatio: number;
  minNumericValidCount: number;
}

export interface DetectionMappings {
  originalBySanitized: Record<string,string>;
  sanitizedByOriginal: Record<string,string>;
  validCounts: Record<string, number>;
}

export interface DetectionResult {
  numeric: string[];
  all: string[];
  mappings: DetectionMappings;
  contextColumns: {
    extIdOriginal: string | null;
    inheritanceIdOriginal: string | null;
    alloyCodeOriginal: string | null;
  };
}

export type Row = Record<string, any>;

export function sanitizeHeaders(headers: string[], mappings?: DetectionMappings): { sanitized: string[]; mappings: DetectionMappings } {
  const originalBySanitized: Record<string,string> = mappings?.originalBySanitized || {};
  const sanitizedByOriginal: Record<string,string> = mappings?.sanitizedByOriginal || {};
  const validCounts: Record<string, number> = mappings?.validCounts || {};
  const used = new Set<string>();
  const sanitized = headers.map((orig, idx) => {
    let base = (orig ?? '').toString().replace(/["'`]/g, '').trim();
    base = base.replace(/[^A-Za-z0-9_.:-]+/g, '_');
    if (!base) base = 'col_' + idx;
    let name = base; let n=1;
    while (used.has(name)) { name = base + '_' + n++; }
    used.add(name);
    originalBySanitized[name] = orig;
    sanitizedByOriginal[orig] = name;
    return name;
  });
  return { sanitized, mappings: { originalBySanitized, sanitizedByOriginal, validCounts } };
}

export function inferNumericColumns(rows: Row[], cfg: DetectionConfig): DetectionResult {
  if (!rows.length) {
    return {
      numeric: [],
      all: [],
      mappings: { originalBySanitized: {}, sanitizedByOriginal: {}, validCounts: {} },
      contextColumns: { extIdOriginal: null, inheritanceIdOriginal: null, alloyCodeOriginal: null }
    };
  }
  const first = rows[0];
  const rawHeaders = Object.keys(first);
  // Discard empty headers
  const allRaw = rawHeaders.filter(h => h && h.trim().length);
  const numericRaw: string[] = [];
  const sampleCap = Math.min(rows.length, cfg.sampleSizeCap);
  for (let hi = 0; hi < rawHeaders.length; hi++) {
    const col = rawHeaders[hi];
    let numericCount = 0; let nonEmpty = 0;
    for (let i = 0; i < sampleCap; i++) {
      const raw = rows[i][col];
      if (raw === '' || raw === null || raw === undefined) continue;
      nonEmpty++;
      if (!isNaN(Number(raw))) numericCount++;
    }
    if (nonEmpty === 0) continue;
    if (isColumnNumericByHeuristic(numericCount, nonEmpty, cfg)) {
      numericRaw.push(col);
    }
  }
  if (!numericRaw.length) {
    numericRaw.push(...rawHeaders); // fallback
  }
  // Sanitize headers
  const { sanitized: sanitizedNumeric, mappings } = sanitizeHeaders(Array.from(new Set(numericRaw)));
  const { sanitized: sanitizedAll } = sanitizeHeaders(allRaw, mappings);

  // Compute valid counts for numeric sanitized columns
  const totalRows = rows.length || 1;
  for (let i = 0; i < sanitizedNumeric.length; i++) {
    const san = sanitizedNumeric[i];
    const orig = mappings.originalBySanitized[san] || san;
    let valid = 0;
    for (let r = 0; r < rows.length; r++) {
      const v = Number(rows[r][orig]);
      if (isFinite(v)) valid++;
    }
    mappings.validCounts[san] = valid;
  }

  // Sparse filtering
  let filteredNumeric = sanitizedNumeric.filter(c => {
    const valid = mappings.validCounts[c] || 0;
    const ratio = valid / totalRows;
    return valid >= cfg.minNumericValidCount && ratio >= cfg.minNumericValidRatio;
  });
  if (filteredNumeric.length && filteredNumeric.length !== sanitizedNumeric.length) {
    // Accept filtered numeric list
    sanitizedNumeric.length = 0; // not strictly needed
    filteredNumeric = filteredNumeric;
  }

  // Identify contextual columns (case-insensitive canonical form comparison)
  const findHeader = (target: string): string | null => {
    const canonTarget = target.toLowerCase();
    for (const orig of Object.values(mappings.originalBySanitized)) {
      if (!orig) continue;
      const canon = orig.toLowerCase().replace(/[^a-z0-9]/g,'');
      if (canon === canonTarget) return orig;
    }
    for (const orig of Object.values(mappings.originalBySanitized)) {
      if (orig && orig.toLowerCase() === target.toLowerCase()) return orig;
    }
    return null;
  };

  const extIdOriginal = findHeader('extid');
  const inheritanceIdOriginal = findHeader('inheritanceid');
  const alloyCodeOriginal = findHeader('alloycode');

  return {
    numeric: filteredNumeric.length ? filteredNumeric : sanitizedNumeric,
    all: sanitizedAll,
    mappings,
    contextColumns: { extIdOriginal, inheritanceIdOriginal, alloyCodeOriginal }
  };
}

function isColumnNumericByHeuristic(numericCount: number, nonEmpty: number, cfg: DetectionConfig): boolean {
  if (numericCount === 0) return false;
  const ratio = numericCount / nonEmpty;
  return (numericCount > 0 && ratio >= cfg.numericHeuristicMinRatio) || numericCount >= cfg.numericHeuristicMinCount;
}
