// Storage abstraction (v2): prefer localStorage; gracefully falls back to cookies if unavailable.
// Includes one-time migration of existing pfcreport_* cookies into localStorage.
class StorageManager {
  private readonly PREFIX = 'pfcreport_';
  private readonly YEARS = 5;
  private readonly MIGRATION_FLAG = this.PREFIX + 'migrated_v2';
  private localAvailable: boolean;

  constructor() {
    this.localAvailable = this.testLocalStorage();
    if (this.localAvailable) {
      this.migrateCookiesOnce();
    }
  }

  // Detect if localStorage is usable (Safari private mode / disabled storage scenarios)
  private testLocalStorage(): boolean {
    try {
      const k = '__pfcreport_test__';
      window.localStorage.setItem(k, '1');
      window.localStorage.removeItem(k);
      return true;
    } catch {
      return false;
    }
  }

  // Cookie helpers (fallback path)
  private setCookie(name: string, value: string) {
    const exp = new Date(); exp.setFullYear(exp.getFullYear() + this.YEARS);
    document.cookie = `${this.PREFIX}${name}=${encodeURIComponent(value)}; expires=${exp.toUTCString()}; path=/; SameSite=Strict`;
  }
  private getCookie(name: string): string | null {
    const key = `${this.PREFIX}${name}=`;
    return document.cookie
      .split(';')
      .map(c => c.trim())
      .find(c => c.startsWith(key))?.slice(key.length) ?? null;
  }

  private deleteCookie(name: string) {
    document.cookie = `${this.PREFIX}${name}=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/; SameSite=Strict`;
  }

  // One-time migration: copy any cookie keys (pfcreport_*) to localStorage, then flag.
  private migrateCookiesOnce() {
    try {
      if (window.localStorage.getItem(this.MIGRATION_FLAG)) return; // already migrated
      const cookiePrefix = this.PREFIX;
      const cookies = document.cookie.split(';').map(c => c.trim());
      cookies.forEach(entry => {
        if (!entry.startsWith(cookiePrefix)) return;
        const eq = entry.indexOf('=');
        if (eq === -1) return;
        const rawKey = entry.slice(0, eq); // pfcreport_key
        const value = entry.slice(eq + 1);
        const shortKey = rawKey.slice(cookiePrefix.length);
        if (!shortKey) return;
        // Don't overwrite if already present in localStorage
        if (window.localStorage.getItem(rawKey) === null && window.localStorage.getItem(cookiePrefix + shortKey) === null) {
          // Store under short (logical) key with prefix applied in set/get
          // We'll use the public set() which re-applies prefix for consistency.
          try {
            this.set(shortKey, decodeURIComponent(value));
          } catch { /* ignore individual failures */ }
        }
        // Optionally delete old cookie (comment out if wanting to keep for rollback)
        this.deleteCookie(shortKey);
      });
      window.localStorage.setItem(this.MIGRATION_FLAG, '1');
    } catch {
      // If migration fails silently continue; cookies remain as fallback.
    }
  }

  set(key: string, value: string) {
    const fullKey = this.PREFIX + key;
    if (this.localAvailable) {
      try {
        window.localStorage.setItem(fullKey, value);
        return;
      } catch {
        // Fall back to cookie if quota or security error
      }
    }
    this.setCookie(key, value);
  }

  get(key: string): string | null {
    const fullKey = this.PREFIX + key;
    if (this.localAvailable) {
      try {
        const v = window.localStorage.getItem(fullKey);
        if (v !== null) return v;
      } catch {
        // ignore and try cookie fallback
      }
    }
    const v = this.getCookie(key);
    return v ? decodeURIComponent(v) : null;
  }

  setJSON(key: string, value: any) {
    try { this.set(key, JSON.stringify(value)); } catch { /* ignore */ }
  }

  getJSON<T = any>(key: string, fallback: T | null = null): T | null {
    const raw = this.get(key);
    if (!raw) return fallback;
    try { return JSON.parse(raw) as T; } catch { return fallback; }
  }
}

export const storage = new StorageManager();
