/** Date & time utility helpers centralizing formatting + conversions.
 * Keep these functions pure & side-effect free.
 */

/** Constant: number of seconds per day. */
export const SECONDS_PER_DAY = 86400;
/** Padding used to convert an inclusive date upper bound into end-of-day unix seconds. */
export const END_OF_DAY_PADDING = SECONDS_PER_DAY - 1; // 86399

/** Format a Date as YYYY-MM-DD (UTC). */
export function formatDateISO(date: Date): string {
  if (!(date instanceof Date) || isNaN(date.getTime())) return '';
  return date.toISOString().split('T')[0];
}

/** Format a Date as e.g. Nov 15 (month short + day). */
export function formatDateShort(date: Date): string {
  if (!(date instanceof Date) || isNaN(date.getTime())) return '';
  return date.toLocaleString('en-US', { month: 'short', day: 'numeric' });
}

/** Format a Date as YYYY-MM-DD HH:MM (24h) in local time. */
export function formatDateTime(date: Date): string {
  if (!(date instanceof Date) || isNaN(date.getTime())) return '';
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  const hh = String(date.getHours()).padStart(2, '0');
  const mm = String(date.getMinutes()).padStart(2, '0');
  return `${y}-${m}-${d} ${hh}:${mm}`;
}

/** Display helper for a start/end date range using short format. */
export function formatDateRangeDisplay(start: Date, end: Date): string {
  return `${formatDateShort(start)} - ${formatDateShort(end)}`;
}

/** Convert a unix seconds timestamp to YYYY-MM-DD (UTC). */
export function unixToDateString(unixTime: number): string {
  if (!isFinite(unixTime)) return '';
  const date = new Date(unixTime * 1000);
  return date.toISOString().split('T')[0];
}

/** Convert a YYYY-MM-DD string to unix seconds (UTC midnight). */
export function dateStringToUnix(dateStr: string): number {
  if (!dateStr) return NaN;
  const date = new Date(dateStr + 'T00:00:00.000Z');
  return Math.floor(date.getTime() / 1000);
}

/** Format calctime for hover label (full date+time). */
export function formatCalctimeForHover(rawCalctime: string | number | null): string {
  if (rawCalctime == null || rawCalctime === '') return '';
  const v = Number(rawCalctime);
  if (!isFinite(v)) return '';
  const date = new Date(v * 1000);
  // Manual fast formatting (avoids Intl allocations in hot path)
  const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const mm = MONTHS[date.getMonth()];
  const dd = date.getDate();
  const yyyy = date.getFullYear();
  const h = date.getHours();
  const m = date.getMinutes();
  const s = date.getSeconds();
  // Zero-pad time components
  const hh = h < 10 ? '0'+h : ''+h;
  const mi = m < 10 ? '0'+m : ''+m;
  const ss = s < 10 ? '0'+s : ''+s;
  return `${mm} ${dd}, ${yyyy}, ${hh}:${mi}:${ss}`;
}
