import { END_OF_DAY_PADDING } from '../utils/dateUtils';

export interface RangeFilter {
  id: string;
  column: string;
  min?: number;
  max?: number;
  isActive?: boolean;
  isDateRangeFilter?: boolean;
}

export interface IdMatcherBundle {
  extId?: { exact?: Set<string>; regex?: RegExp[] };
  alloy?: { exact?: Set<string>; regex?: RegExp[] };
}

export type Row = Record<string, any>;

export interface FilterEnvironment {
  filters: RangeFilter[];
  originalNameBySanitized: Record<string,string>;
}

export function buildRowPredicate(env: FilterEnvironment): (row: Row) => boolean {
  const active = env.filters.filter(f => f.isActive !== false);
  if (!active.length) return () => true;
  // Pre-resolve column mappings
  const resolved = active.map(f => ({ f, orig: env.originalNameBySanitized[f.column] || f.column }));
  return (row: Row) => {
    for (let i = 0; i < resolved.length; i++) {
      const { f, orig } = resolved[i];
      const rawValue = row[orig];
      if (rawValue === '' || rawValue === null || rawValue === undefined) continue; // treat missing as pass-through? (mirrors original logic which 'continue's)
      const num = Number(rawValue);
      if (!isFinite(num)) continue; // skip non-numeric
      if (f.min !== undefined && num < f.min) return false;
      if (f.max !== undefined && num > f.max) return false;
    }
    return true;
  };
}

export function filterIndices(rows: Row[], predicate: (row: Row) => boolean): number[] {
  const out: number[] = [];
  for (let i = 0; i < rows.length; i++) {
    if (predicate(rows[i])) out.push(i);
  }
  return out;
}
