// Visual extension beyond Plotly's max axis position (1.0) for Y3.
// We shift the rendered SVG groups horizontally after render.
const Y3_AXIS_PIXEL_OFFSET = 28; // Increase if you want Y3 further right.

function shiftY3AxisIfPresent() {
  const plotDiv = document.getElementById('pfcLinePlot');
  if (!plotDiv) return;
  const layout: any = (plotDiv as any).layout;
  if (!layout || !layout.yaxis3) return; // Nothing to shift
  // Collect groups that belong to y3 (ticks, title, axis line container)
  const groups = Array.from(plotDiv.querySelectorAll('g')) as Element[];
  const y3Groups = groups.filter(g => {
    const cls = g.getAttribute('class') || '';
    return /(^|\s)y3/.test(cls);
  });
  if (!y3Groups.length) return;
  y3Groups.forEach(g => {
    const el = g as any; // Access style generically
    if (!el.style) return;
    const prev: string = el.style.transform || '';
    if (prev.includes('translateX')) {
      el.style.transform = prev.replace(/translateX\([^)]*\)/, `translateX(${Y3_AXIS_PIXEL_OFFSET}px)`);
    } else {
      el.style.transform = prev + (prev ? ' ' : '') + `translateX(${Y3_AXIS_PIXEL_OFFSET}px)`;
    }
    // Keep axis interactive
    el.style.pointerEvents = 'auto';
    el.dataset.y3ShiftApplied = '1';
  });
}

function scheduleY3AxisShift() {
  // Reapply across multiple frames to catch late-rendered tick labels
  shiftY3AxisIfPresent();
  requestAnimationFrame(() => shiftY3AxisIfPresent());
  requestAnimationFrame(() => requestAnimationFrame(() => shiftY3AxisIfPresent()));
  setTimeout(() => shiftY3AxisIfPresent(), 80);
}
