function applyDateRangeFilter() {
  if (!selectedStartDate || !selectedEndDate) return;
  
  // Find the calctime column from available columns
  const calctimeColumn = allColumns.find(col => isCalctimeColumn(col));
  if (!calctimeColumn) {
    console.error('No calctime column found for date range filtering');
    return;
  }
  
  // Convert dates to unix timestamps (same logic as manual calctime filters)
  const startTimestamp = selectedStartDate.getTime() / 1000;
  const endTimestamp = selectedEndDate.getTime() / 1000 + END_OF_DAY_PADDING; // inclusive end-of-day
  
  // Remove existing active (or any stray) date range filter for this column
  if (activeDateRangeFilterId) {
    filters = filters.filter(f => f.id !== activeDateRangeFilterId);
  } else {
    filters = filters.filter(f => !(f.column === calctimeColumn && f.isDateRangeFilter));
  }
  const newId = 'daterange_' + Date.now() + Math.random().toString(36).slice(2);
  filters.push({
    id: newId,
    column: calctimeColumn,
    min: startTimestamp,
    max: endTimestamp,
    isActive: true,
    isDateRangeFilter: true
  });
  activeDateRangeFilterId = newId;
  
  // Update the display text using consistent format MMM D - MMM D (no year)
  if (timeRangeInput) timeRangeInput.value = formatDateRangeDisplay(selectedStartDate, selectedEndDate);
  
  console.log('Applied date range filter to column:', calctimeColumn, 'Range:', startTimestamp, 'to', endTimestamp);
  
  // Use the existing filter system
  persistFilters();
  renderFilterList();
  applyFilters();
  renderLinePlot();
  renderHistogram();
}

// (formatDateRangeDisplay now imported)

// Sync the date range picker UI from an existing persisted calctime filter (if any)
function syncDateRangePickerFromFilters() {
  if (!calctimeOriginal && !calctimeSanitized) return; // no calctime context
  if (!timeRangeInput) return;
  // Prefer an explicit date range filter that was previously marked
  const calctimeCol = calctimeSanitized || calctimeOriginal || '';
  if (!calctimeCol) return;
  // Identify candidate filters (must have both min & max)
  const candidates = filters.filter(f => f.column === calctimeCol && f.min !== undefined && f.max !== undefined);
  if (!candidates.length) return;
  // Prefer one explicitly created by date picker
  let chosen = candidates.find(f => (f as any).isDateRangeFilter);
  if (!chosen) chosen = candidates[0];
  activeDateRangeFilterId = chosen.id;
  const min = chosen.min!; const max = chosen.max!;
  if (!isFinite(min) || !isFinite(max) || max <= min) return;
  // If it is a date-range style filter we stored end-of-day by adding END_OF_DAY_PADDING seconds; detect & adjust.
  const DAY_END_PADDING = END_OF_DAY_PADDING; // unified constant
  let adjustedEnd = max;
  if (Math.abs((max - min) % SECONDS_PER_DAY - DAY_END_PADDING) <= 2 || (max - min) > DAY_END_PADDING) {
    // Heuristic: if we added padding previously, subtract it for display
    adjustedEnd = max - DAY_END_PADDING;
  }
  const startDate = new Date(min * 1000);
  const endDate = new Date(adjustedEnd * 1000);
  // Guard against invalid dates
  if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) return;
  selectedStartDate = startDate;
  selectedEndDate = endDate;
  timeRangeInput.value = formatDateRangeDisplay(startDate, endDate);
  // Update flatpickr selection if available
  if (flatpickrInstance && typeof flatpickrInstance.setDate === 'function') {
    try { flatpickrInstance.setDate([startDate, endDate], false); } catch {}
    // Enforce custom short display (flatpickr may inject year based on its config/state)
    timeRangeInput.value = formatDateRangeDisplay(startDate, endDate);
  }
}

function clearDateRangeFilter() {
  selectedStartDate = null;
  selectedEndDate = null;
  
  // Remove any date range filters
  filters = filters.filter(f => !f.isDateRangeFilter);
  activeDateRangeFilterId = null;
  
  if (timeRangeInput) {
    timeRangeInput.value = '';
    timeRangeInput.placeholder = 'Start — End';
  }
  
  console.log('Cleared date range filter');
  
  // Use the existing filter system
  persistFilters();
  renderFilterList();
  applyFilters();
  renderLinePlot();
  renderHistogram();
}

// Remove the currently tracked date range filter (if present) and re-render
function removeActiveDateRangeFilter() {
  if (!activeDateRangeFilterId) return;
  const before = filters.length;
  filters = filters.filter(f => f.id !== activeDateRangeFilterId);
  activeDateRangeFilterId = null;
  selectedStartDate = null; selectedEndDate = null;
  if (timeRangeInput) { timeRangeInput.value = ''; timeRangeInput.placeholder = 'Start — End'; }
  persistFilters();
  renderFilterList();
  applyFilters();
  renderLinePlot();
  renderHistogram();
  console.log('Removed date range filter (picker clear). Filters before/after:', before, filters.length);
}

