function persistFilters() {
  const minimal = filters.map(f => ({
    column: f.column,
    min: f.min,
    max: f.max,
    isActive: f.isActive,
    isDateRangeFilter: f.isDateRangeFilter === true
  }));
  storage.setJSON(FILTERS_KEY, minimal);
  // Invalidate cached row predicate so newly added/removed/toggled filters (incl. calctime)
  // take effect immediately on next data access. Previously this stayed stale, causing
  // calctime/date range filters to appear non-functional after refactors.
  rowPredicate = null;
}

function restoreFilters() {
  const saved = storage.getJSON<Array<{column:string;min?:number;max?:number;isActive?:boolean;isDateRangeFilter?:boolean}>>(FILTERS_KEY, []);
  if (!saved) return;
  filters = saved.filter(s => s.column).map(s => ({
    id: 'f' + Math.random().toString(36).slice(2),
    column: s.column.toLowerCase(),
    min: s.min,
    max: s.max,
    isActive: s.isActive !== false, // default true
    isDateRangeFilter: s.isDateRangeFilter === true
  }));

  // Backward compatibility: if no filter explicitly marked as date range but we have one on calctime with both bounds, mark it.
  if (!filters.some(f => f.isDateRangeFilter) && filters.length) {
    const candidate = filters.find(f => f.column === 'calctime' && typeof f.min === 'number' && typeof f.max === 'number');
    if (candidate) {
      candidate.isDateRangeFilter = true;
    }
  }

  // Restore activeDateRangeFilterId if exactly one date range filter exists
  const dateRangeFilters = filters.filter(f => f.isDateRangeFilter);
  if (dateRangeFilters.length === 1) {
    activeDateRangeFilterId = dateRangeFilters[0].id;
  } else if (dateRangeFilters.length > 1) {
    // pick the most recently overlapping one (largest span) as active heuristic
    dateRangeFilters.sort((a,b) => ((b.max??0)-(b.min??0)) - ((a.max??0)-(a.min??0)));
    activeDateRangeFilterId = dateRangeFilters[0].id;
  }
}
