function generateAMHighlightShapes(): any[] {
  if (!calctimeOriginal || isSequentialMode) return [];
  
  const shapes: any[] = [];
  
  // Use the same filtering logic as the plot traces to get actually visible data
  const validIndices = getValidRowIndices();
  
  // Find the full time range of the ACTUALLY FILTERED data (including range filters)
  let minTimestamp = Infinity;
  let maxTimestamp = -Infinity;
  
  for (let vi = 0; vi < validIndices.length; vi++) {
    const index = validIndices[vi];
    const row = filteredRows[index];
    const calctimeValue = row[calctimeOriginal!];
    if (calctimeValue === null || calctimeValue === undefined) continue;
    const timestamp = Number(calctimeValue);
    if (!isFinite(timestamp)) continue;
    minTimestamp = Math.min(minTimestamp, timestamp);
    maxTimestamp = Math.max(maxTimestamp, timestamp);
  }
  
  if (!isFinite(minTimestamp) || !isFinite(maxTimestamp)) {
    console.log('No valid timestamps found for AM highlighting', {
      filteredRowsCount: filteredRows.length,
      validIndicesCount: validIndices.length,
      hasCalctime: !!calctimeOriginal,
      isSequential: isSequentialMode
    });
    return shapes;
  }
  
  // Convert to UTC dates and find the date range
  const startDate = new Date(minTimestamp * 1000);
  const endDate = new Date(maxTimestamp * 1000);
  
  // Start from the beginning of the first day (UTC)
  const firstDay = new Date(startDate);
  firstDay.setUTCHours(0, 0, 0, 0);
  
  // End at the end of the last day (UTC)
  const lastDay = new Date(endDate);
  lastDay.setUTCHours(23, 59, 59, 999);
  
  console.log('AM highlighting range (fully filtered data):', {
    filteredRowsCount: filteredRows.length,
    validIndicesCount: validIndices.length,
    firstDay: firstDay.toISOString(),
    lastDay: lastDay.toISOString(),
    dataRange: `${startDate.toISOString()} to ${endDate.toISOString()}`,
    totalDays: Math.ceil((lastDay.getTime() - firstDay.getTime()) / (24 * 60 * 60 * 1000))
  });
  
  // Generate AM shapes for each day in the range
  const currentDate = new Date(firstDay);
  
  while (currentDate <= lastDay) {
    // Create AM period for this date (UTC midnight to UTC noon)
    const startOfDay = new Date(currentDate);
    startOfDay.setUTCHours(0, 0, 0, 0);
    
    const endOfAM = new Date(currentDate);
    endOfAM.setUTCHours(12, 0, 0, 0);
    
    // Add gray rectangle shape for AM period
    shapes.push({
      type: 'rect',
      xref: 'x',
      yref: 'paper',
      x0: startOfDay.toISOString(),
      y0: 0,
      x1: endOfAM.toISOString(),
      y1: 1,
      fillcolor: 'rgba(128, 128, 128, 0.15)',
      line: { width: 0 },
      layer: 'below'
    });
    
    // Move to next day (UTC)
    currentDate.setUTCDate(currentDate.getUTCDate() + 1);
  }
  
  console.log(`Generated ${shapes.length} AM highlight shapes covering ${Math.ceil((lastDay.getTime() - firstDay.getTime()) / (24 * 60 * 60 * 1000))} days (based on ${validIndices.length}/${filteredRows.length} fully filtered rows)`);
  return shapes;
}


