let resizeTimeout: number;
function handleResize() {
  clearTimeout(resizeTimeout);
  resizeTimeout = window.setTimeout(() => {
    // Relayout existing plots with new dimensions
    if (linePlotDiv && (linePlotDiv as any).data) {
      Plotly.Plots.resize(linePlotDiv);
    }
    if (histDiv && (histDiv as any).data) {
      Plotly.Plots.resize(histDiv);
    }
  }, CONFIG.RESIZE_DEBOUNCE_MS);
}

window.addEventListener('resize', handleResize);

// Add click handler to clear focus when clicking outside signals
// But only in specific UI areas, not in plots or Plotly controls
document.addEventListener('click', (e) => {
  if (!e.target || !(e.target as Element).closest('.signal-item')) {
    // Only clear focus if clicked in sidebar areas, not in plots or Plotly controls
    const target = e.target as Element;
    const isInSidebar = target.closest('.sidebar');
    const isInPlot = target.closest('.plots-container, .js-plotly-plot, .plotly');
    const isPlotlyControl = target.closest('[class*="plotly"], .modebar, .modebar-btn');
    
    if (isInSidebar && !isInPlot && !isPlotlyControl && focusedSignal) {
      clearSignalFocus();
    }
  }
});

function fitYAxisToVisibleRange() {
  if (!activeColumns.size || !filteredRows.length) return;
  
  const currentLayout = (linePlotDiv as any).layout;
  if (!currentLayout || !currentLayout.xaxis) return;
  
  // Get current X axis range (what's currently visible)
  const xRange = currentLayout.xaxis.range;
  if (!xRange || xRange.length !== 2) return;
  
  const [xMin, xMax] = xRange;
  const xIsDate = !isSequentialMode && !!calctimeOriginal;
  
  // Separate Y1, Y2 and Y3 axis calculations
  let y1Min = Infinity, y1Max = -Infinity, hasY1Data = false;
  let y2Min = Infinity, y2Max = -Infinity, hasY2Data = false;
  let y3Min = Infinity, y3Max = -Infinity, hasY3Data = false;
  
  for (const col of activeColumns) {
    const y = getNumericSeries(col);
    const xBase = getX();
  const isY2 = y2AxisSignals.has(col);
  const isY3 = y3AxisSignals.has(col);
    
    for (let i = 0; i < y.length && i < xBase.length; i++) {
      const yVal = y[i];
      const xVal = xBase[i];
      
      if (!isFinite(yVal) || xVal === null) continue;
      
      // Convert x value for comparison
      let xCompare: number;
      if (xIsDate && xVal instanceof Date) {
        xCompare = xVal.getTime();
        // Convert xMin, xMax to timestamps for comparison
        const xMinTime = new Date(xMin).getTime();
        const xMaxTime = new Date(xMax).getTime();
        if (xCompare < xMinTime || xCompare > xMaxTime) continue;
      } else {
        xCompare = Number(xVal);
        if (xCompare < xMin || xCompare > xMax) continue;
      }
      
      // This point is within the visible X range - assign to appropriate axis
      if (isY3) {
        y3Min = Math.min(y3Min, yVal);
        y3Max = Math.max(y3Max, yVal);
        hasY3Data = true;
      } else if (isY2) {
        y2Min = Math.min(y2Min, yVal);
        y2Max = Math.max(y2Max, yVal);
        hasY2Data = true;
      } else {
        y1Min = Math.min(y1Min, yVal);
        y1Max = Math.max(y1Max, yVal);
        hasY1Data = true;
      }
    }
  }
  
  const updates: any = {};
  
  // Update Y1 axis if we have data
  if (hasY1Data && y1Min !== y1Max) {
    const y1Range = y1Max - y1Min;
    const y1Padding = y1Range * 0.05;
    const y1MinFit = y1Min - y1Padding;
    const y1MaxFit = y1Max + y1Padding;
    
    updates['yaxis.range'] = [y1MinFit, y1MaxFit];
    updates['yaxis.autorange'] = false;
  }
  
  // Update Y2 axis if we have data
  if (hasY2Data && y2Min !== y2Max) {
    const y2Range = y2Max - y2Min;
    const y2Padding = y2Range * 0.05;
    const y2MinFit = y2Min - y2Padding;
    const y2MaxFit = y2Max + y2Padding;
    
    updates['yaxis2.range'] = [y2MinFit, y2MaxFit];
    updates['yaxis2.autorange'] = false;
  }
  
  // Update Y3 axis if we have data
  if (hasY3Data && y3Min !== y3Max) {
    const y3Range = y3Max - y3Min;
    const y3Padding = y3Range * 0.05;
    const y3MinFit = y3Min - y3Padding;
    const y3MaxFit = y3Max + y3Padding;
    updates['yaxis3.range'] = [y3MinFit, y3MaxFit];
    updates['yaxis3.autorange'] = false;
  }

  // Apply updates if any
  if (Object.keys(updates).length > 0) {
    Plotly.relayout(linePlotDiv, updates);
    log('Fit Y axes to visible range:', {
      xRange: [xMin, xMax],
      y1Range: hasY1Data ? [y1Min, y1Max] : 'no data',
      y2Range: hasY2Data ? [y2Min, y2Max] : 'no data',
      y3Range: hasY3Data ? [y3Min, y3Max] : 'no data'
    });
  }
}

