/** Wildcard / pattern matching helpers.
 * Supports a user syntax where '*' matches any substring.
 * We also provide an 'implicit surrounding *' rule at a higher level if desired.
 */

/** Escape regex special chars except we will expand '*' ourselves. */
function escapeRegex(lit: string): string {
  return lit.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** Convert a wildcard pattern (may include '*') into an anchored regex. */
export function wildcardToRegex(pattern: string): RegExp | null {
  if (!pattern) return null;
  if (pattern === '*') return null; // treat single * as match-all sentinel
  if (!pattern.includes('*')) return null; // caller can treat as exact token
  const anchoredStart = pattern.startsWith('*') ? '' : '^';
  const anchoredEnd = pattern.endsWith('*') ? '' : '$';
  const core = pattern.split('*').map(p => escapeRegex(p)).join('.*');
  try { return new RegExp(anchoredStart + core + anchoredEnd, 'i'); } catch { return null; }
}

/** Split a comma-separated list into trimmed non-empty tokens. */
export function splitTokenList(raw: string | null | undefined): string[] {
  if (!raw) return [];
  return raw.split(',').map(s => s.trim()).filter(Boolean);
}

export interface CompiledPatternSet {
  exact?: Set<string>;    // lowercase exact matches
  regex: RegExp[];        // compiled wildcard regex patterns
}

/** Compile a list of user-entered wildcard tokens into exact + regex sets. */
export function compilePatterns(tokens: string[]): CompiledPatternSet {
  const exact: string[] = [];
  const regex: RegExp[] = [];
  tokens.forEach(t => {
    const rx = wildcardToRegex(t);
    if (rx) regex.push(rx); else if (t !== '*') exact.push(t.toLowerCase());
  });
  return { exact: exact.length ? new Set(exact) : undefined, regex };
}

/** Test a value against include/exclude compiled sets. */
export function matchWithIncludeExclude(
  value: unknown,
  include: CompiledPatternSet | null,
  exclude: CompiledPatternSet | null
): boolean {
  const str = String(value ?? '').trim();
  const lower = str.toLowerCase();
  if (exclude) {
    if (exclude.exact && exclude.exact.has(lower)) return false;
    if (exclude.regex.some(r => r.test(str))) return false;
  }
  if (include && (include.exact || include.regex.length)) {
    const exactOk = include.exact ? include.exact.has(lower) : false;
    const regexOk = include.regex.some(r => r.test(str));
    if (!exactOk && !regexOk) return false;
  }
  return true;
}
