// Lightweight regression utilities for scatter plot statistics
// Provides L2 (least squares) and approximate L1 (least absolute deviation) affine fits.
// No external dependencies; designed for moderate-sized datasets in browser.

export interface LinearFitResult {
  slope: number;
  intercept: number;
  // Optional diagnostics
  r2?: number;           // For L2
  mae?: number;          // For L1
  iterations?: number;   // For L1 IRLS
  method: 'l2' | 'l1-irls' | 'l1-theil-sen';
  n: number;             // number of points used
}

// Basic least squares affine fit y = m x + b
export function computeLeastSquares(x: number[], y: number[]): LinearFitResult | null {
  const n = x.length;
  if (n !== y.length || n < 2) return null;
  let sumX = 0, sumY = 0, sumXX = 0, sumXY = 0;
  for (let i = 0; i < n; i++) {
    const xi = x[i]; const yi = y[i];
    sumX += xi; sumY += yi; sumXX += xi*xi; sumXY += xi*yi;
  }
  const meanY = sumY / n;
  const denom = n * sumXX - sumX * sumX;
  if (Math.abs(denom) < 1e-12) return null; // near-vertical / degenerate
  const slope = (n * sumXY - sumX * sumY) / denom;
  const intercept = (sumY - slope * sumX) / n;
  // R^2
  let ssRes = 0, ssTot = 0;
  for (let i = 0; i < n; i++) {
    const yi = y[i];
    const fi = slope * x[i] + intercept;
    const diff = yi - fi;
    ssRes += diff * diff;
    const dy = yi - meanY;
    ssTot += dy * dy;
  }
  const r2 = ssTot > 0 ? 1 - (ssRes / ssTot) : undefined;
  return { slope, intercept, r2, method: 'l2', n };
}

// Approximate L1 regression using Iteratively Reweighted Least Squares (IRLS)
// with fallback to Theil-Sen estimator if IRLS degenerates.
export function computeL1AffineFit(x: number[], y: number[]): LinearFitResult | null {
  const n = x.length;
  if (n !== y.length || n < 2) return null;
  // Seed with least squares. If fails, attempt Theil-Sen only.
  const ls = computeLeastSquares(x, y);
  if (!ls) return theilSen(x, y);
  let m = ls.slope;
  let b = ls.intercept;
  const maxIter = 25;
  const eps = 1e-6;
  let lastChange = Infinity;
  for (let iter = 0; iter < maxIter; iter++) {
    // Compute weights w_i = 1 / max(eps, |r_i|)
    let sumW = 0, sumWX = 0, sumWY = 0, sumWXX = 0, sumWXY = 0;
    for (let i = 0; i < n; i++) {
      const xi = x[i]; const ri = y[i] - (m * xi + b);
      const w = 1 / Math.max(eps, Math.abs(ri));
      sumW += w; sumWX += w * xi; sumWY += w * y[i]; sumWXX += w * xi * xi; sumWXY += w * xi * y[i];
    }
    const denom = sumW * sumWXX - sumWX * sumWX;
    if (Math.abs(denom) < 1e-12) break; // degeneracy
    const newM = (sumW * sumWXY - sumWX * sumWY) / denom;
    const newB = (sumWY - newM * sumWX) / sumW;
    lastChange = Math.max(Math.abs(newM - m), Math.abs(newB - b));
    m = newM; b = newB;
    if (lastChange < 1e-6) {
      const mae = computeMAE(x, y, m, b);
      return { slope: m, intercept: b, mae, iterations: iter + 1, method: 'l1-irls', n };
    }
  }
  if (!isFinite(m) || !isFinite(b)) return theilSen(x, y);
  const mae = computeMAE(x, y, m, b);
  return { slope: m, intercept: b, mae, iterations: maxIter, method: 'l1-irls', n };
}

function computeMAE(x: number[], y: number[], m: number, b: number): number {
  let sum = 0;
  for (let i = 0; i < x.length; i++) sum += Math.abs(y[i] - (m * x[i] + b));
  return sum / x.length;
}

// Theil-Sen estimator (robust, median of slopes) + median intercept
// O(n^2) worst case; we down-sample pairs if large.
function theilSen(x: number[], y: number[]): LinearFitResult | null {
  const n = x.length;
  if (n < 2) return null;
  const maxPairs = 20000; // cap for performance
  const slopes: number[] = [];
  // If n is small do all pairs else random sample
  if ((n * (n - 1)) / 2 <= maxPairs) {
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        const dx = x[j] - x[i];
        if (Math.abs(dx) < 1e-12) continue;
        slopes.push((y[j] - y[i]) / dx);
      }
    }
  } else {
    // Random sampling of pairs
    const iterations = maxPairs;
    for (let k = 0; k < iterations; k++) {
      const i = Math.floor(Math.random() * n);
      let j = Math.floor(Math.random() * n);
      if (j === i) j = (j + 1) % n;
      const dx = x[j] - x[i];
      if (Math.abs(dx) < 1e-12) continue;
      slopes.push((y[j] - y[i]) / dx);
    }
  }
  if (!slopes.length) return null;
  slopes.sort((a,b)=>a-b);
  const mid = Math.floor(slopes.length / 2);
  const slope = slopes.length % 2 ? slopes[mid] : 0.5 * (slopes[mid - 1] + slopes[mid]);
  // Intercept via median of y - m x
  const intercepts = new Array(n);
  for (let i = 0; i < n; i++) intercepts[i] = y[i] - slope * x[i];
  intercepts.sort((a,b)=>a-b);
  const midI = Math.floor(n / 2);
  const intercept = n % 2 ? intercepts[midI] : 0.5 * (intercepts[midI - 1] + intercepts[midI]);
  const mae = computeMAE(x, y, slope, intercept);
  return { slope, intercept, mae, method: 'l1-theil-sen', n };
}
