/** Color palette + deterministic hashing + custom overrides. */

/** Base palette (mirrors CONFIG.COLOR_PALETTE initial ordering). */
export const BASE_COLOR_PALETTE = [
  '#1f77b4', '#ff7f0e', '#2ca02c', '#d62728', '#9467bd', '#8c564b',
  '#e377c2', '#7f7f7f', '#bcbd22', '#17becf', '#aec7e8', '#ffbb78',
  '#98df8a', '#ff9896', '#c5b0d5', '#c49c94', '#f7b6d3', '#c7c7c7',
  '#dbdb8d', '#9edae5', '#393b79', '#637939', '#8c6d31', '#843c39',
  '#7b4173', '#5254a3', '#8ca252', '#bd9e39', '#ad494a', '#a55194'
] as const;

/** Simple string hash -> non-negative integer. */
function hashString(str: string): number {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) - h) + str.charCodeAt(i);
    h |= 0; // force 32-bit
  }
  return h < 0 ? -h : h;
}

/** Deterministic color choice from column name, overridable by custom map. */
export function colorFor(column: string, custom: Record<string, string> = {}): string {
  if (custom[column]) return custom[column];
  const h = hashString(column);
  return BASE_COLOR_PALETTE[h % BASE_COLOR_PALETTE.length];
}

/** Cycle assignment: map active columns sequentially onto palette order. */
export function assignSequentialColors(columns: string[]): Record<string, string> {
  const result: Record<string, string> = {};
  columns.forEach((c, i) => {
    result[c] = BASE_COLOR_PALETTE[i % BASE_COLOR_PALETTE.length];
  });
  return result;
}
